        signed_b = -bv if effective_sb else bv
        total = signed_a + signed_b
        if total == 0:
            if ca == "zero" and cb == "zero" and sa == effective_sb:
                sign = sa
            else:
                sign = int(mode == 3)
            return result(sign << 31)
        sign = int(total < 0)
