import cocotb
from cocotb.clock import Clock
from cocotb.triggers import FallingEdge, RisingEdge, Timer
from random import Random


SIGN = 0x80000000
FRAC = 0x007FFFFF
INF = 0x7F800000
QNAN = 0x7FC00001
MAX_FINITE = 0x7F7FFFFF
MAX_UNITS = ((1 << 24) - 1) << 253


def exponent(x):
    return (x >> 23) & 255


def is_nan(x):
    return exponent(x) == 255 and (x & FRAC) != 0


def is_snan(x):
    return is_nan(x) and (x & 0x00400000) == 0


def is_inf(x):
    return (x & 0x7FFFFFFF) == INF


def is_zero(x):
    return (x & 0x7FFFFFFF) == 0


def is_subnormal(x):
    return exponent(x) == 0 and (x & FRAC) != 0


def units(x):
    """Magnitude of a finite binary32 value in units of 2**-149."""
    e = exponent(x)
    f = x & FRAC
    if e == 0:
        return f
    return ((1 << 23) | f) << (e - 1)


def packed_result(bits, snan, divzero=0, ine=0, overflow=0,
                  underflow=0, mask=0xFFFFFFFF):
    mag = bits & 0x7FFFFFFF
    flags = {
        "inf": int(mag == INF),
        "snan": snan,
        "qnan": int(mag > INF),
        "ine": ine,
        "overflow": overflow,
        "underflow": underflow,
        "zero": int(mag == 0),
        "div_by_zero": divzero,
    }
    return bits, mask, flags


def nan_result(a, b, snan):
    an = is_nan(a)
    bn = is_nan(b)
    if an != bn:
        sign = (a if an else b) & SIGN
        return packed_result(QNAN | sign, snan)
    return packed_result(QNAN, snan, mask=0x7FFFFFFF)


def rounded_finite(num, den, sign, op, mode, snan, divzero):
    """Round positive num/den, expressed in units of 2**-149."""
    if num == 0:
        return packed_result(sign << 31, snan, divzero)

    tiny = num < (den << 23)

    # Find floor(log2(num / den)).
    k = num.bit_length() - den.bit_length()
    if k >= 0:
        if num < (den << k):
            k -= 1
    elif (num << (-k)) < den:
        k -= 1

    shift = max(0, k - 23)
    divisor = den << shift
    q, rem = divmod(num, divisor)

    increment = False
    if rem:
        if mode == 0:
            twice = rem << 1
            if twice > divisor:
                increment = True
            elif twice == divisor:
                increment = bool(q & 1)
                # Division's documented non-IEEE subnormal tie rule.
                if op == 3 and shift == 0 and 1 <= q < (1 << 23) - 1:
                    increment = True
        elif mode == 2:
            increment = sign == 0
        elif mode == 3:
            increment = sign == 1

    rounded = (q + int(increment)) << shift
    overflow = rounded > MAX_UNITS

    if overflow:
        to_inf = mode == 0 or (mode == 2 and sign == 0) or (
            mode == 3 and sign == 1
        )
        bits = (sign << 31) | (INF if to_inf else MAX_FINITE)
        return packed_result(bits, snan, divzero, ine=1, overflow=1)

    inexact = int(rounded * den != num)
    if tiny and not inexact and op in (2, 3):
        underflow = None
    else:
        underflow = int(tiny and inexact)

    if rounded == 0:
        magnitude = 0
    elif rounded < (1 << 23):
        magnitude = rounded
    else:
        rk = rounded.bit_length() - 1
        exp = rk - 22
        significand = rounded >> (rk - 23)
        magnitude = (exp << 23) | (significand & FRAC)

    return packed_result(
        (sign << 31) | magnitude, snan, divzero,
        ine=inexact, overflow=0, underflow=underflow
    )


def reference(op, mode, a, b):
    if op >= 4 or (is_inf(a) and is_inf(b)):
        return None

    snan = int(is_snan(a) or is_snan(b))
    sa = a >> 31
    sb = b >> 31

    if is_nan(a) or is_nan(b):
        result = nan_result(a, b, snan)
    elif op in (0, 1):
