import cocotb
from cocotb.triggers import Timer
from random import Random


SIGN = 0x80000000
MAG = 0x7fffffff
INF = 0x7f800000
QNAN = 0x7fc00001
MAX_FINITE = 0x7f7fffff


def classify(bits):
    exponent = (bits >> 23) & 255
    fraction = bits & 0x7fffff
    if exponent == 255:
        if fraction == 0:
            return "inf"
        if fraction & 0x400000:
            return "qnan"
        return "snan"
    if exponent == 0:
        if fraction == 0:
            return "zero"
        return "sub"
    return "normal"


def finite_units(bits):
    """Magnitude in units of 2**-149."""
    exponent = (bits >> 23) & 255
    fraction = bits & 0x7fffff
    if exponent == 0:
        return fraction
    return (0x800000 | fraction) << (exponent - 1)


def reference(op, mode, a, b):
    # None denotes an entirely unspecified transaction.
    if op >= 4:
        return None

    ca = classify(a)
    cb = classify(b)
    if ca == "inf" and cb == "inf":
        return None

    sa = (a >> 31) & 1
    sb = (b >> 31) & 1
    signaling = int(ca == "snan" or cb == "snan")
    nan_a = ca == "snan" or ca == "qnan"
    nan_b = cb == "snan" or cb == "qnan"
    ine_unspecified = op == 3 and ca == "sub"

    def result(bits, mask=0xffffffff, ine=0, overflow=0,
               underflow=0, divzero=0):
        magnitude = bits & MAG
        flags = (
            int(magnitude == INF),
            signaling,
            int(magnitude > INF),
            None if ine_unspecified else ine,
            overflow,
            underflow,
            int(magnitude == 0),
            divzero,
        )
        return bits, mask, flags

    if nan_a or nan_b:
        if nan_a and nan_b:
            return result(QNAN, MAG)
        sign = sa if nan_a else sb
        return result(QNAN | (sign << 31))

    if op == 0 or op == 1:
        effective_sb = sb ^ int(op == 1)
        if ca == "inf":
            return result(INF | (sa << 31))
        if cb == "inf":
            return result(INF | (effective_sb << 31))

        va = finite_units(a)
        vb = finite_units(b)
        total = (-va if sa else va) + (-vb if effective_sb else vb)
        if total == 0:
            if va == 0 and vb == 0 and sa == effective_sb:
                sign = sa
            else:
                sign = int(mode == 3)
            return result(sign << 31)
        sign = int(total < 0)
        numerator = abs(total)
        denominator = 1

    elif op == 2:
        sign = sa ^ sb
        if (ca == "inf" and cb == "zero") or (
            cb == "inf" and ca == "zero"
        ):
            return result(QNAN, MAG)
        if ca == "inf" or cb == "inf":
            return result(INF | (sign << 31))
        if ca == "zero" or cb == "zero":
            return result(sign << 31)
        numerator = finite_units(a) * finite_units(b)
        denominator = 1 << 149

    else:
        sign = sa ^ sb
        if ca == "zero" and cb == "zero":
            return result(QNAN, MAG)
        if ca == "inf":
            return result(INF | (sign << 31))
        if cb == "inf":
            return result(sign << 31)
        if cb == "zero":
            return result(INF | (sign << 31), divzero=1)
        if ca == "zero":
            return result(sign << 31)
        numerator = finite_units(a) << 149
        denominator = finite_units(b)

    # Determine the binary exponent of the exact magnitude, expressed in
    # units of the smallest subnormal.
    exponent = numerator.bit_length() - denominator.bit_length()
    if exponent >= 0:
        if numerator < (denominator << exponent):
            exponent -= 1
    elif (numerator << (-exponent)) < denominator:
        exponent -= 1

    shift = max(0, exponent - 23)
    divisor = denominator << shift
    significand, remainder = divmod(numerator, divisor)

    increment = False
    if remainder:
        if mode == 0:
            twice = remainder * 2
            if twice > divisor:
                increment = True
            elif twice == divisor:
                increment = bool(significand & 1)
                # Specified division deviation for subnormal halfway cases.
                if op == 3 and shift == 0 and 0 < significand < 0x800000:
                    increment = True
        elif mode == 2:
            increment = sign == 0
        elif mode == 3:
            increment = sign == 1

    if increment:
        significand += 1
    if significand >= 0x1000000:
        significand >>= 1
        shift += 1

    # Overflow is assessed after rounding to precision with an unbounded
    # exponent, not merely by comparing the exact value to max finite.
    overflow = int(shift > 253)
    inexact = int(remainder != 0 or overflow != 0)
    tiny = numerator < (denominator << 23)

    if overflow:
        away = mode == 0 or (mode == 2 and sign == 0) or (
            mode == 3 and sign == 1
        )
        bits = (INF if away else MAX_FINITE) | (sign << 31)
    elif significand == 0:
        bits = sign << 31
    elif shift == 0 and significand < 0x800000:
        bits = (sign << 31) | significand
    else:
        exponent_field = shift + 1
        bits = (sign << 31) | (exponent_field << 23) | (
            significand - 0x800000
        )

    if tiny and not inexact and (op == 2 or op == 3):
        underflow = None
    else:
        underflow = int(tiny and inexact)
    return result(bits, ine=inexact, overflow=overflow, underflow=underflow)


def check(dut, expected, transaction, index, phase):
    if expected is None:
        return

    bits, mask, flags = expected
