from cocotb.triggers import Timer
from random import Random


SIGN = 0x80000000
FRAC = 0x007FFFFF
INF = 0x7F800000
QNAN = 0x7FC00001
MAX_UNITS = ((1 << 24) - 1) << 253


def fields(x):
    sign = x >> 31
    exponent = (x >> 23) & 0xFF
    fraction = x & FRAC
    is_nan = exponent == 255 and fraction != 0
    is_snan = is_nan and (fraction & 0x400000) == 0
    is_inf = exponent == 255 and fraction == 0
    is_zero = exponent == 0 and fraction == 0
    is_sub = exponent == 0 and fraction != 0
    return sign, exponent, fraction, is_nan, is_snan, is_inf, is_zero, is_sub


def units(x):
    exponent = (x >> 23) & 0xFF
    fraction = x & FRAC
    if exponent == 0:
        return fraction
    return ((1 << 23) | fraction) << (exponent - 1)


def result_record(out, mask, snan, ine=0, overflow=0, underflow=0,
                  div_by_zero=0):
    magnitude = out & 0x7FFFFFFF
    return {
        "out": out,
        "mask": mask,
        "inf": int(magnitude == INF),
        "snan": int(snan),
        "qnan": int(magnitude > INF),
        "ine": ine,
        "overflow": overflow,
        "underflow": underflow,
        "zero": int(magnitude == 0),
        "div_by_zero": div_by_zero,
    }


def oracle(op, mode, a, b):
    if op >= 4:
        return None

    sa, ea, fa, na, sna, ia, za, suba = fields(a)
    sb, eb, fb, nb, snb, ib, zb, subb = fields(b)

    # Both-infinity operations are explicitly unspecified.
    if ia and ib:
        return None

    snan = sna or snb
    ine_unspecified = op == 3 and suba

    if na or nb:
        if na and nb:
            out = QNAN
            mask = 0x7FFFFFFF
        else:
            out = QNAN | ((sa if na else sb) << 31)
            mask = 0xFFFFFFFF
        rec = result_record(out, mask, snan)
        if ine_unspecified:
            rec["ine"] = None
        return rec

    if op == 2 and ((ia and zb) or (ib and za)):
        return result_record(QNAN, 0x7FFFFFFF, snan)

    if op == 3 and za and zb:
        return result_record(QNAN, 0x7FFFFFFF, snan)

    if op <= 1:
        if ia or ib:
            sign = sa if ia else (sb ^ op)
            return result_record((sign << 31) | INF, 0xFFFFFFFF, snan)
    elif op == 2:
        if ia or ib:
            return result_record(((sa ^ sb) << 31) | INF,
                                 0xFFFFFFFF, snan)
    else:
        if ia or zb:
            dbz = int(zb and not ia and not za)
            rec = result_record(((sa ^ sb) << 31) | INF,
                                0xFFFFFFFF, snan, div_by_zero=dbz)
            if ine_unspecified:
                rec["ine"] = None
            return rec
        if ib or za:
            rec = result_record((sa ^ sb) << 31, 0xFFFFFFFF, snan)
            if ine_unspecified:
                rec["ine"] = None
